import{_ as n,o as i,c as t,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Plan — 3-10-2-platform-statistics-overview","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-2-platform-statistics-overview/plan.md","filePath":"feature/admin-management/3-10-2-platform-statistics-overview/plan.md"}'),a={name:"feature/admin-management/3-10-2-platform-statistics-overview/plan.md"};function c(d,e,r,s,h,g){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="plan-—-3-10-2-platform-statistics-overview" tabindex="-1">Plan — 3-10-2-platform-statistics-overview <a class="header-anchor" href="#plan-—-3-10-2-platform-statistics-overview" aria-label="Permalink to &quot;Plan — 3-10-2-platform-statistics-overview&quot;">​</a></h1><p>Nguồn: <a href="./spec.html">spec</a>, <a href="./../confirmed-decisions-2026-10-01.html">quyết định đã duyệt</a>.</p><p>Thiết kế, file paths, API, migration, thứ tự và rủi ro: <strong>mục 5</strong> của <a href="./../plan.html">plan tổng thể</a>. Các global constraints và Review Focus trong plan tổng thể áp dụng đầy đủ.</p><p>Thành phần: AdminStatisticsService; ReportPeriod; AdminStatisticsPanel.</p><h2 id="dashboard-foundation-—-2026-10-02" tabindex="-1">Dashboard foundation — 2026-10-02 <a class="header-anchor" href="#dashboard-foundation-—-2026-10-02" aria-label="Permalink to &quot;Dashboard foundation — 2026-10-02&quot;">​</a></h2><ul><li>Design: giữ font Inter và palette BrandHub (cam <code>#f05a28</code>, trắng <code>#ffffff</code>, canvas <code>#fafafa</code>, xám <code>#71717a</code>, sidebar <code>#09090b</code>); màu lấy qua theme token. Header căn trái; vùng nội dung tối đa khoảng1440px;4 KPI; biểu đồ đăng ký chiếm2/3, phân bố tài khoản1/3; hàng dưới là các việc cần xử lý và tài khoản mới. Không trang trí gradient hoặc số tăng trưởng chưa có căn cứ.</li><li>URL <code>/admin</code> là Tổng quan, <code>?view=users</code> là danh sách; filter status trong URL dùng cho drill-down. Giữ query state khi refresh/back. Sidebar Admin riêng trong component hiện có, không đổi nghiệp vụ Monitoring hoặc quyền người dùng thường.</li><li>API đọc riêng <code>GET /api/v1/admin/statistics?days=30&amp;timezone=Asia/Ho_Chi_Minh</code>. ChỉADMIN; days∈7,30,90; timezone∈UTC,Asia/Ho_Chi_Minh; sai→400. Không mutation hoặc migration.</li><li>DTO: <code>generatedAt</code>, <code>timezone</code>, <code>days</code>, <code>periodStart</code>, <code>periodEnd</code> (ISO timestamps; cuối kỳ là now), <code>totalUsers</code>, <code>activeUsers30d</code>, <code>totalAgencies</code>, <code>flaggedUsers</code>, <code>pendingVerificationUsers</code>, <code>deactivatedUsers</code>, <code>pendingSanctions</code>, <code>newUsersInPeriod</code>; <code>strikes:{yellow,orange,red}</code>; <code>accountStatuses:[{status,count}]</code>; <code>registrations:[{date,count}]</code> đủ ngày theo timezone. Không trường riêng tư.</li><li>Backend dùng Clock, SQL/JPA tổng hợp có tham số và transaction read-only REPEATABLE_READ để giữ snapshot nhất quán. Đã xác minh lastLoginAt chỉ được cập nhật tại completeLogin (password/2FA) và OAuth login; refresh không gọi completeLogin. Strike chỉ removed_at IS NULL, converted_to_id IS NULL, expires_at &gt; now, created_at &lt;= now. Pending review trạng tháiPENDING. Agency loại deleted_at khácnull hoặc statusSOFT_DELETED theo enum hiện có.</li><li>Frontend: <code>adminStatisticsService.ts</code>, <code>AdminOverviewPanel.tsx</code>, các component biểu đồ/summary cần thiết, <code>admin/index.tsx</code>, AccountsPanel và Sidebar. Overview loading/empty/error/forbidden, retry/refresh; query key gồm actor+days+timezone; sau đổi tài khoản không dùng dữ liệu người cũ. Dữ liệu cũ có chỉ báo nếu refresh thất bại.</li><li>Giữ chức năng strike đang chạy; cải thiện avatar/tên/email, toolbar, trạng thái và bố cục bảng. Các FR chưa triển khai hiển thị chưa sẵn sàng, không giả lập approve/send/export.</li><li>Ruling: thực hiện trong working tree hiện tại để giữ các thay đổi Admin/auth chưa commit và tiếp tục localhost người dùng đang xem; không reset/checkout hoặc commit các thay đổi ngoài phạm vi.</li><li>Ruling: không thêm tài chính/ranking Agency ở bước thiết kế dashboard này vì phải hoàn tất ánh xạ nguồn thu/bài/hoạt động của giai đoạn sau; dùng trạng thái chưa có dữ liệu thay số giả.</li></ul><p>Trình tự: test nghiệp vụ RED → backend/data GREEN → API/security → UI/locale → build/integration. Locale thêm trong brandhub-web/src/i18n/locales/vi/admin.json và en/admin.json; theme dùng token hiện có. Không sửa monitoring.</p><h2 id="ui-refinement-—-2026-10-04" tabindex="-1">UI refinement — 2026-10-04 <a class="header-anchor" href="#ui-refinement-—-2026-10-04" aria-label="Permalink to &quot;UI refinement — 2026-10-04&quot;">​</a></h2><ol><li>Dùng working tree hiện tại vì đây là tiếp tục dashboard/auth đang được người dùng xem; giữ mọi thay đổi có sẵn, không commit/push.</li><li>Tách <code>AdminOverviewPanel</code> thành orchestration và component summary/charts/recent users trong <code>src/pages/admin/components/</code>, chỉ dùng <code>adminStatisticsService</code>/<code>adminAccountService</code> hiện hữu. Không thêm endpoint/migration.</li><li>Cập nhật <code>AdminSidebar</code>, phần Admin của <code>Navbar</code>, <code>admin/index.tsx</code>, bảng người dùng/dialog: bố cục mẫu, navigation grouping, role thật, bỏ notification mock cho ADMIN, làm rõ strike. Tôn trọng phạm vi người dùng thường và Monitoring.</li><li>Bổ sung song song <code>src/i18n/locales/{vi,en}/admin.json</code>: <code>navigation.utilities</code>, <code>.planned</code>, <code>overview.pendingHint</code>, <code>.attentionHint</code>, <code>.verificationHint</code>, <code>.flaggedReviewHint</code>, <code>.sanctionHint</code>, <code>.noPending</code>, <code>.periodTotal</code>, <code>.snapshot</code>, <code>accounts.rulesTitle</code>, <code>.rulesHint</code>, <code>.clearFilters</code>, <code>.page</code>, <code>.reviewPending</code>. Không đổi định nghĩa activeUsers30d.</li><li>Chạy Playwright Admin/auth hiện có, thêm kiểm tra nội dung sai của HTML không lọt vào UI, các mục chưa sẵn sàng, trường hợp tổng user=0 và viewport tablet. Build, lint các file đổi; xem ảnh VI/EN sáng/tối và browser smoke API thật.</li><li>Ghi bằng chứng tại test.md/task.md. File HTML là tài liệu tham khảo, không phải hợp đồng dữ liệu; ghi rõ các khác biệt đã sửa trong ứng dụng.</li></ol>',9)])])}const p=n(a,[["render",c]]);export{m as __pageData,p as default};
